window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[228]={"id":"228","numero":228,"titre":"Ulcère de jambe","objectifs":[{"id":"228-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’un ulcère de jambe","contenu":"<p>L'<span class=\"kw-def\">ulcère de jambe</span> = <strong>perte de substance dermique chronique</strong> qui <strong>ne cicatrise pas</strong> et évolue <span class=\"kw-chiffre\">depuis &gt; 1 mois</span>. Le caractère <strong>chronique</strong> est intrinsèque à la définition — une plaie aiguë récente n'est pas un ulcère.</p>\n      <p>Au niveau des <strong>membres inférieurs</strong>, l'ulcère est le plus souvent d'origine <span class=\"kw-etio\">vasculaire</span> — <strong>veineuse et/ou artérielle</strong> — par <span class=\"kw-def\">ischémie tissulaire</span>.</p>\n      <table >\n        <thead><tr><th>Donnée épidémiologique</th><th>Repère</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Fréquence</strong></td><td><span class=\"kw-clinique\">Fréquent</span> et <span class=\"kw-clinique\">invalidant</span> ; à l'origine de nombreuses hospitalisations</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Prévalence</span></strong> (veineux + artériels)</td><td>Augmente avec l'âge : <span class=\"kw-chiffre\">1 %</span> entre <span class=\"kw-chiffre\">60-70 ans</span> ; <span class=\"kw-chiffre\">2-5 %</span> après <span class=\"kw-chiffre\">80 ans</span></td></tr>\n          <tr><td><strong>Sex-ratio</strong></td><td>Prédominance <strong>féminine</strong> de l'ulcère <span class=\"kw-etio\">veineux</span> (<span class=\"kw-chiffre\">1,5 F / 1 H</span>)</td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"228-2","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir diagnostiquer un ulcère veineux, artériel, mixte","contenu":"<p><strong>Objectif EDN le plus tombé de l'item</strong> (6 ⭐ bruts au QCM). L'<span class=\"kw-etio\">ulcère veineux</span> est de loin le plus fréquent (<span class=\"kw-chiffre\">~80 %</span> des ulcères) ; l'<span class=\"kw-etio\">ulcère mixte</span> et l'<span class=\"kw-etio\">ulcère artériel</span> complètent le trio vasculaire. Le diagnostic est <strong>clinique</strong>, confirmé par l'<span class=\"kw-bio\">IPS</span> et l'<span class=\"kw-imagerie\">écho-doppler</span>.</p>\n      <table >\n        <thead><tr><th>Critère</th><th><span class=\"kw-clinique\">Ulcère veineux</span></th><th><span class=\"kw-clinique\">Ulcère artériel</span></th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Terrain</span></strong></td>\n            <td><span class=\"kw-clinique\">Femme &gt; 50 ans</span> (1,5 F/1 H) ; ATCD de <span class=\"kw-etio\">TVP</span>, varices, surpoids</td>\n            <td><span class=\"kw-clinique\">Homme &gt; 50 ans</span> ; FDR cardiovasculaires ; ATCD d'ischémie d'effort (<span class=\"kw-clinique\">claudication</span> intermittente)</td>\n          </tr>\n          <tr>\n            <td><strong>Localisation</strong></td>\n            <td><span class=\"kw-clinique\">Péri-malléolaire</span> jusqu'au 1/3 inférieur du mollet ; bord <strong>régulier</strong></td>\n            <td>Zones de <span class=\"kw-clinique\">frottement / appui</span> : orteils, dos et bord externe du pied, talon ; parfois face antérieure de jambe (ulcère « suspendu »)</td>\n          </tr>\n          <tr>\n            <td><strong>Nombre / taille</strong></td>\n            <td>Unique ; souvent <strong>étendu</strong>, parfois circonférentiel</td>\n            <td>Unique ou multiple ; <strong>petite taille</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Douleur</strong></td>\n            <td><strong>Peu ou pas douloureux</strong></td>\n            <td><span class=\"kw-alerte\">Douloureux</span>, habituellement intense</td>\n          </tr>\n          <tr>\n            <td><strong>Profondeur / fond</strong></td>\n            <td>Superficiel, non creusant (pas d'exposition tendineuse) ; fond <strong>exsudatif, fibrineux</strong></td>\n            <td><span class=\"kw-alerte\">Creusant</span>, risque d'exposition des articulations / tendons / os ; fond <strong>atone</strong> (pâle, propre)</td>\n          </tr>\n          <tr>\n            <td><strong>Peau péri-ulcéreuse</strong></td>\n            <td>\n              <strong>Varices :</strong> télangiectasies ; varicosités ; <span class=\"kw-clinique\">couronne phlébectasique</span> (corona phlebectatica)<br>\n              <strong>Capillarite :</strong> <span class=\"kw-clinique\">dermite ocre</span> ; <span class=\"kw-clinique\">atrophie blanche</span><br>\n              <strong>Dermo-épiderme :</strong> <span class=\"kw-clinique\">eczéma variqueux</span><br>\n              <strong>Hypodermite :</strong> aiguë / subaiguë ; lipodermatosclérose<br>\n              <strong>Examen artériel :</strong> normal +++\n            </td>\n            <td>\n              <strong>Trophicité :</strong> peau <span class=\"kw-clinique\">luisante, dépilée</span> ; <span class=\"kw-clinique\">baisse de la température cutanée</span><br>\n              <strong>Vascularisation :</strong> <span class=\"kw-clinique\">pâleur à la surélévation</span> ; <span class=\"kw-clinique\">érythro-cyanose de déclivité</span> ; allongement du temps de recoloration pulpaire<br>\n              <strong>Pouls :</strong> <span class=\"kw-alerte\">abolition des pouls périphériques</span><br>\n              <strong>Mauvaise tolérance :</strong> déshabitation des pulpes digitales ; fonte de la coque talonnière\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">IPS</span></strong></td>\n            <td><span class=\"kw-chiffre\">0,9 – 1,3</span> (<span class=\"kw-imagerie\">IPS</span> normal = <span class=\"kw-clinique\">ulcère veineux</span> pur)</td>\n            <td><span class=\"kw-chiffre\">&lt; 0,9</span> diminué ; <span class=\"kw-chiffre\">0,7 – 0,9</span> = ulcère mixte à prédominance veineuse ; <span class=\"kw-chiffre\">&gt; 1,3</span> = artères calcifiées</td>\n          </tr>\n          <tr>\n            <td><strong>Imagerie</strong></td>\n            <td><span class=\"kw-imagerie\">Écho-doppler veineux</span> des membres inférieurs (debout) : reflux superficiel / profond ; obstruction profonde</td>\n            <td><span class=\"kw-imagerie\">Écho-doppler artériel</span> : confirme l'artériopathie, niveau et type des lésions ; recherche un AAA</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>Ulcère mixte.</strong> Ulcère de mécanisme <strong>préférentiellement veineux</strong> mais s'accompagnant d'une <span class=\"kw-etio\">AOMI modérée</span> qui n'explique pas à elle seule l'ulcère. Y penser devant un <strong>ulcère d'allure veineuse à cicatrisation traînante</strong>, avec pouls abolis et pression d'orteil abaissée. <span class=\"kw-imagerie\">Écho-doppler veineux</span> + <span class=\"kw-imagerie\">IPS</span> systématiques ; <span class=\"kw-imagerie\">écho-doppler</span> artériel si pouls abolis, signes d'AOMI ou IPS &lt; 0,9 / &gt; 1,3.\n      </div>\n      <div class=\"callout callout-warn\">\n        <strong>Piège tombé en annale.</strong> La <span class=\"kw-clinique\">couronne phlébectasique</span> de la cheville (corona phlebectatica) = capillarite hypertrophique — signe d'insuffisance veineuse chronique avancée, à reconnaître sur photo.\n      </div>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/228/complications-cutanees-ivc.jpg\" alt=\"Planche des complications cutanées de l'insuffisance veineuse chronique : dermite ocre, atrophie blanche de Millian, dermo-hypodermite de stase, eczéma variqueux\" loading=\"lazy\">\n        <figcaption>Complications cutanées de l'insuffisance veineuse chronique péri-ulcéreuse : dermite ocre (macules pigmentées brunes), atrophie blanche de Millian (plaques ivoire péri-malléolaires), <span class=\"kw-clinique\">eczéma</span> variqueux, lipodermatosclérose. Source : fiche source EDN item 228.</figcaption>\n      </figure>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 225 — Artériopathie oblitérante - anévrysme · 226 — Thrombose veineuse profonde - EP</em></p>","frequence":6},{"id":"228-3","rang":"B","rubrique":"Eléments physiopathologiques","titre":"Connaître les principaux mécanismes physiopathologiques des ulcères de jambe artériels, veineux et mixtes","contenu":"<p>Les trois mécanismes vasculaires convergent vers une <span class=\"kw-def\">hypoxie tissulaire</span> chronique responsable des troubles trophiques puis de la perte de substance.</p>\n      <table >\n        <thead><tr><th>Type</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Veineux</strong><br>(le plus fréquent)</td>\n            <td>\n              Dû à une <span class=\"kw-def\">hypertension veineuse</span> (stase créant une <span class=\"kw-clinique\">hypertension</span> cutanée). Trois causes :<br>\n              <strong>Reflux superficiel :</strong> <span class=\"kw-def\">incompétence valvulaire</span> des veines superficielles / perforantes ; varices (maladie veineuse essentielle)<br>\n              <strong>Reflux / obstruction profonde :</strong> syndrome <span class=\"kw-etio\">post-thrombotique</span><br>\n              <strong>Déficience de la pompe musculaire</strong> du mollet<br>\n              → souffrance microcirculatoire : altération de la barrière endothéliale ; diapédèse leucocytaire et inflammation ; <span class=\"kw-def\">manchon péricapillaire de fibrine</span> ; piégeage des facteurs de croissance qui réduit les capacités de cicatrisation\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Artériel</strong></td>\n            <td>Hypoxie tissulaire <strong><span class=\"kw-etio\">ischémique</span></strong>, conséquence d'une <span class=\"kw-alerte\">AOMI sévère</span> au <span class=\"kw-def\">stade</span> d'<span class=\"kw-def\">ischémie critique chronique</span></td>\n          </tr>\n          <tr>\n            <td><strong>Mixte</strong></td>\n            <td>Mécanisme <strong>préférentiellement veineux</strong> + <span class=\"kw-etio\">AOMI modérée</span> qui n'explique pas à elle seule l'ulcère (à prédominance veineuse, ou <span class=\"kw-clinique\">ulcère veineux</span> à composante artérielle)</td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 225 — Artériopathie oblitérante - anévrysme · 226 — Thrombose veineuse profonde - EP</em></p>","frequence":0},{"id":"228-4","rang":"A","rubrique":"Contenu multimédia","titre":"Photographie d’un ulcère veineux typique","contenu":"<p>L'<span class=\"kw-etio\">ulcère veineux typique</span> se reconnaît sur photo à un faisceau de signes cohérents.</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/228/ulcere-veineux-typique.png\" alt=\"Ulcère veineux typique : ulcération péri-malléolaire interne, étendue, à bords réguliers, fond fibrineux exsudatif, sur peau avec dermite ocre\" loading=\"lazy\">\n        <figcaption><span class=\"kw-clinique\">Ulcère veineux</span> typique : <span class=\"kw-clinique\">ulcération</span> <strong>péri-malléolaire</strong>, étendue, à <strong>bords réguliers</strong>, fond fibrineux et exsudatif, entourée de signes d'insuffisance veineuse (dermite ocre, varices). Source : fiche source EDN item 228.</figcaption>\n      </figure>\n      <table >\n        <thead><tr><th>Signe</th><th>Sémiologie typique</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Siège</strong></td><td><span class=\"kw-clinique\">Péri-malléolaire</span> (souvent <span class=\"kw-clinique\">malléole interne</span>) jusqu'au 1/3 inférieur du mollet</td></tr>\n          <tr><td><strong>Bords</strong></td><td><strong>Réguliers</strong>, souples, au même niveau que l'ulcère (bon <span class=\"kw-def\">pronostic</span>)</td></tr>\n          <tr><td><strong>Taille / fond</strong></td><td>Souvent étendu, parfois circonférentiel ; fond <strong><span class=\"kw-clinique\">exsudatif et fibrineux</span></strong>, superficiel non creusant</td></tr>\n          <tr><td><strong>Douleur</strong></td><td><strong>Peu ou pas douloureux</strong></td></tr>\n          <tr><td><strong>Peau péri-ulcéreuse</strong></td><td><span class=\"kw-clinique\">Dermite ocre</span> ; <span class=\"kw-clinique\">atrophie blanche</span> ; <span class=\"kw-clinique\">eczéma variqueux</span> ; varices et <span class=\"kw-clinique\">couronne phlébectasique</span></td></tr>\n        </tbody>\n      </table>","frequence":2},{"id":"228-5","rang":"A","rubrique":"Contenu multimédia","titre":"Photographie d’un ulcère artériel typique","contenu":"<p>L'<span class=\"kw-etio\">ulcère artériel typique</span> s'oppose point par point à l'<span class=\"kw-clinique\">ulcère veineux</span>.</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/228/ulcere-arteriel-typique.png\" alt=\"Ulcère artériel typique : ulcération de petite taille, creusante, à fond atone pâle, siégeant sur une zone d'appui du pied, sur peau luisante et dépilée\" loading=\"lazy\">\n        <figcaption><span class=\"kw-clinique\">Ulcère artériel</span> typique : <span class=\"kw-clinique\">ulcération</span> <strong>de petite taille</strong>, <strong>creusante</strong>, à fond atone pâle, siégeant sur une zone d'appui ou de frottement du pied, sur peau luisante, dépilée et froide. Source : fiche source EDN item 228.</figcaption>\n      </figure>\n      <table >\n        <thead><tr><th>Signe</th><th>Sémiologie typique</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Siège</strong></td><td>Zones de <span class=\"kw-clinique\">frottement / appui</span> : orteils, dos et bord externe du pied, talon ; parfois face antérieure de jambe (ulcère « suspendu »)</td></tr>\n          <tr><td><strong>Taille / fond</strong></td><td><strong>Petite taille</strong> ; <span class=\"kw-alerte\">creusant</span> avec risque d'exposition tendineuse / osseuse ; fond <strong>atone</strong> (pâle, propre)</td></tr>\n          <tr><td><strong>Douleur</strong></td><td><span class=\"kw-alerte\">Douloureux</span>, habituellement intense</td></tr>\n          <tr><td><strong>Peau péri-ulcéreuse</strong></td><td>Peau <span class=\"kw-clinique\">luisante, dépilée</span> ; froide ; <span class=\"kw-clinique\">pâleur à la surélévation</span>, <span class=\"kw-clinique\">érythro-cyanose de déclivité</span> ; <span class=\"kw-alerte\">pouls abolis</span></td></tr>\n        </tbody>\n      </table>","frequence":1},{"id":"228-6","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’une angiodermite nécrotique","contenu":"<p>L'<span class=\"kw-etio\">angiodermite nécrotique</span> (<span class=\"kw-etio\">ulcère de Martorell</span>) est un ulcère <strong>non lié à une AOMI</strong> : son diagnostic est clinique, sur un faisceau d'arguments positifs et négatifs.</p>\n      <table >\n        <thead><tr><th>Élément</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">Terrain</span></strong></td><td><span class=\"kw-clinique\">Femme &gt; 50 ans</span> ; <span class=\"kw-etio\">HTA</span> ++ ; <span class=\"kw-etio\">diabète</span> ++</td></tr>\n          <tr>\n            <td><strong>Sémiologie</strong></td>\n            <td>\n              <strong>Début :</strong> brutal, par une <span class=\"kw-clinique\">plaque purpurique ou livedoïde</span> extensive<br>\n              <strong><span class=\"kw-clinique\">Évolution</span> :</strong> rapide vers une <span class=\"kw-alerte\">nécrose noirâtre</span> (ulcérations superficielles)<br>\n              <strong>Siège :</strong> face antéro-externe de la partie inférieure de la jambe<br>\n              <strong>Bords :</strong> nécrotiques, irréguliers, « en carte de géographie »<br>\n              <strong>Douleur :</strong> <span class=\"kw-alerte\">très douloureux, insomniant</span> (y compris au décubitus)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Arguments négatifs</strong><br>(à vérifier)</td>\n            <td>\n              <strong>Pouls :</strong> présents<br>\n              <strong>Axes vasculaires :</strong> <span class=\"kw-clinique\">grands axes artériels</span> et veineux normaux<br>\n              <strong>Bilan immuno :</strong> cryoglobulinémie négative ; <span class=\"kw-bio\">FAN</span> (= AAN) et <span class=\"kw-bio\">ANCA</span> négatifs\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>Note PEC.</strong> La greffe cutanée en pastilles a souvent un effet cicatrisant <strong>et <span class=\"kw-ttt\">antalgique</span></strong>.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 224 — <span class=\"kw-etio\">HTA</span> · 247 — Diabète</em></p>","frequence":0},{"id":"228-7","rang":"B","rubrique":"Eléments physiopathologiques","titre":"Connaître les bases physiopathologiques de l’angiodermite nécrotique","contenu":"<p>L'angiodermite nécrotique est un <span class=\"kw-def\">infarctus cutané</span> causé par une <strong><span class=\"kw-def\">occlusion artériolaire</span></strong> — une <span class=\"kw-def\">artériolosclérose</span> des vaisseaux du <strong>derme</strong>.</p>\n      <div class=\"callout callout-warn\">\n        <strong>À distinguer de l'<span class=\"kw-clinique\">ulcère artériel</span>.</strong> L'atteinte porte sur les <strong><span class=\"kw-def\">artérioles dermiques</span></strong>, pas sur les gros troncs artériels : les <strong><span class=\"kw-clinique\">pouls périphériques restent présents</span></strong> et les <span class=\"kw-clinique\">grands axes artériels</span> sont normaux. C'est ce qui explique le <span class=\"kw-def\">terrain</span> <span class=\"kw-etio\">HTA</span> / <span class=\"kw-etio\">diabète</span> et la dissociation « ulcère nécrotique très douloureux mais pouls conservés ».\n      </div>","frequence":0},{"id":"228-8","rang":"B","rubrique":"Contenu multimédia","titre":"Photographie d’une angiodermite nécrotique","contenu":"<p>L'<span class=\"kw-etio\">angiodermite nécrotique</span> typique se reconnaît à sa <span class=\"kw-clinique\">nécrose</span> noirâtre à <span class=\"kw-clinique\">bords irréguliers</span> sur la face antéro-externe de la jambe.</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/228/angiodermite-necrotique.png\" alt=\"Angiodermite nécrotique : ulcération à nécrose noirâtre, bords irréguliers en carte de géographie, halo péri-ulcéreux livedoïde, sur la face antéro-externe de jambe\" loading=\"lazy\">\n        <figcaption>Angiodermite nécrotique (<span class=\"kw-etio\">ulcère de Martorell</span>) : <strong>nécrose noirâtre</strong>, <span class=\"kw-clinique\">bords nécrotiques irréguliers</span> « en carte de géographie », <span class=\"kw-clinique\">halo péri-ulcéreux cyanique et livedoïde</span>, <span class=\"kw-clinique\">face antéro-externe de la partie inférieure de jambe</span>. <span class=\"kw-clinique\">Lésion</span> <strong><span class=\"kw-alerte\">très douloureuse et insomniante</span></strong>. Source : fiche source EDN item 228.</figcaption>\n      </figure>","frequence":0},{"id":"228-9","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les causes non vasculaires d’ulcères de jambe","contenu":"<p>Beaucoup plus rares que les ulcères vasculaires, les <span class=\"kw-etio\">causes non vasculaires</span> sont à évoquer systématiquement devant certains <span class=\"kw-alerte\">drapeaux rouges</span>.</p>\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">Drapeaux rouges</span> — évoquer une étiologie non vasculaire si :</strong>\n        <br>• Examens artériels et veineux <strong>normaux</strong>\n        <br>• <span class=\"kw-clinique\">Évolution</span> ulcérante <strong>rapide</strong>, ou évolution traînante et inhabituelle\n        <br>• <span class=\"kw-alerte\">Absence d'évolution favorable après 2-3 mois de traitement bien conduit</span>\n        <br>• Anomalie du fond, du bord, de la périphérie, ou siège atypique\n      </div>\n      <table >\n        <thead><tr><th>Cause</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Neuro-trophique</strong></td><td><span class=\"kw-etio\">Mal perforant plantaire</span> : complication d'une neuropathie évoluée avec perte de la sensation douloureuse ; débute par une <span class=\"kw-clinique\">hyperkératose</span> qui s'ulcère sur les zones d'appui plantaires (talon, tête des métatarsiens). Causes : <span class=\"kw-etio\">diabète</span>, anomalies médullaires, neuropathies sensitives</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Infectieux</span></strong></td><td><span class=\"kw-etio\">Ecthyma</span> : infection cutanée à <span class=\"kw-bio\">Streptocoque A</span>, petite <span class=\"kw-clinique\">ulcération</span> à érythème périphérique puis croûte noirâtre ; mycobactérioses, mycoses profondes, parasitoses</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Inflammatoire</span></strong></td><td><span class=\"kw-etio\">Pyoderma gangrenosum</span> : <span class=\"kw-clinique\">ulcération</span> superficielle à <span class=\"kw-clinique\">bords irréguliers</span>, clapiers purulents, bourrelet périphérique, extension centrifuge rapide ; associé dans <span class=\"kw-chiffre\">2/3</span> des cas à une pathologie (hémopathie, <span class=\"kw-etio\">MICI</span>, cancer)</td></tr>\n          <tr><td><strong>Hémopathie</strong></td><td>Anémie hémolytique <span class=\"kw-etio\">congénitale</span> (<span class=\"kw-etio\">drépanocytose</span>, thalassémie) — chez un sujet <strong>jeune</strong> ; syndromes myéloprolifératifs (ulcérations chroniques et nécrotiques)</td></tr>\n          <tr><td><strong>Cancers</strong></td><td>Cancers cutanés (CBC, <span class=\"kw-etio\">carcinome épidermoïde</span>, <span class=\"kw-clinique\">mélanome</span>) devant une <span class=\"kw-clinique\">ulcération</span> chronique rebelle de <strong>petite taille</strong>, d'aspect atypique</td></tr>\n          <tr><td><strong>Vascularites</strong></td><td><span class=\"kw-clinique\">Évolution</span> d'un <span class=\"kw-clinique\">purpura</span> nécrotique : <span class=\"kw-etio\">SAPL</span> ; vascularites cutanées leucocytoclasiques ; vascularites systémiques (PAN, lupus systémique, cryoglobulinémies)</td></tr>\n          <tr><td><strong>Médicaments</strong></td><td>Au long cours : <span class=\"kw-ttt\">hydroxy-urée</span>, <span class=\"kw-ttt\">interféron</span> ; ulcères nombreux et rebelles, régressent en quelques semaines après l'arrêt</td></tr>\n          <tr><td><strong>Pathomimie</strong></td><td>Diagnostic d'<strong>élimination</strong></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Dogme EDN.</strong> Tout <strong><span class=\"kw-clinique\">ulcère veineux</span> qui ne guérit pas après plusieurs mois de traitement</strong> justifie une <span class=\"kw-bio\">biopsie</span> (recherche d'un <span class=\"kw-etio\">carcinome épidermoïde</span>).\n      </div>\n      <div class=\"callout callout-info\">\n        <strong><span class=\"kw-def\">Diagnostic différentiel</span> (rang C).</strong> L'<span class=\"kw-etio\">artériolopathie calcifiante</span> (calciphylaxie) donne des nécroses cutanées des <strong>cuisses et de l'abdomen</strong>, compliquant des anomalies phosphocalciques de l'<span class=\"kw-etio\">insuffisance rénale chronique</span>.\n      </div>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/228/pyoderma-gangrenosum.png\" alt=\"Pyoderma gangrenosum : ulcération superficielle à bords irréguliers décollés, bourrelet périphérique inflammatoire violacé, clapiers purulents\" loading=\"lazy\">\n        <figcaption>Pyoderma gangrenosum : <span class=\"kw-clinique\">ulcération</span> superficielle à <span class=\"kw-clinique\">bords irréguliers</span>, clapiers purulents, <strong>bourrelet périphérique <span class=\"kw-etio\">inflammatoire</span></strong> caractéristique, à extension centrifuge rapide. Source : fiche source EDN item 228.</figcaption>\n      </figure>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 96 — Neuropathie périphérique · 247 — <span class=\"kw-etio\">Diabète</span> · 282 — MICI · 194 — Lupus - SAPL · 302 — <span class=\"kw-clinique\">Tumeur cutanée</span> - épithéliale - mélanique · 264 — <span class=\"kw-ci\">Insuffisance rénale</span> chronique</em></p>","frequence":0},{"id":"228-10","rang":"A","rubrique":"Prise en charge","titre":"Connaître la compression et ses modalités","contenu":"<p>La <span class=\"kw-def\">compression</span> est le <strong>pilier du traitement de l'<span class=\"kw-clinique\">ulcère veineux</span></strong> — elle lutte contre l'<span class=\"kw-clinique\">œdème</span> et diminue le reflux.</p>\n      <div class=\"callout callout-danger\">\n        <strong>Indication selon le type d'ulcère.</strong> La compression permet la cicatrisation des ulcères <strong>veineux</strong>, mais elle est <strong>inutile dans les autres ulcères</strong>, voire <span class=\"kw-ci\">contre-indiquée en cas d'ischémie sévère</span>. <span class=\"kw-ci\">Contre-indication</span> formelle si <span class=\"kw-ci\">IPS &lt; 0,6</span>.\n      </div>\n      <table >\n        <thead><tr><th>Situation</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Ulcère veineux</span></strong><br>(<span class=\"kw-imagerie\">IPS</span> 0,8 – 1,3)</td>\n            <td>\n              <strong>Pression :</strong> haut niveau, <span class=\"kw-chiffre\">30-40 mmHg</span> à la cheville<br>\n              <strong>Classe :</strong> <span class=\"kw-chiffre\">classe 3</span> (<span class=\"kw-chiffre\">25-36 mmHg</span>) pour les ulcères cicatrisés ; <span class=\"kw-chiffre\">classe 4</span> (<span class=\"kw-chiffre\">&gt; 36 mmHg</span>) pour les ulcères ouverts<br>\n              <strong>Modalités :</strong> privilégier les compressions <strong>multicouches</strong> ; port <strong>toute la journée</strong>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Ulcère mixte</strong><br>à prédominance veineuse</td>\n            <td>\n              Compression autorisée seulement si <span class=\"kw-chiffre\">IPS &gt; 0,7</span><br>\n              <strong>Pression :</strong> abaissée sous <span class=\"kw-chiffre\">&lt; 30 mmHg</span><br>\n              <strong>Matériel :</strong> bandes à <strong>étirement court</strong>, sous <span class=\"kw-def\">surveillance</span> médicale\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Ulcère artériel</span></strong> / ischémie sévère</td>\n            <td>Compression <span class=\"kw-ci\">inutile à contre-indiquée</span> — prioriser la <span class=\"kw-ttt\">revascularisation</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 225 — Artériopathie oblitérante - anévrysme</em></p>","frequence":4},{"id":"228-11","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître l’intérêt de l’imagerie : échodoppler artério-veineux en 1ère intention","contenu":"<p>Le bilan paraclinique d'un ulcère de jambe vise le <strong><span class=\"kw-def\">diagnostic étiologique</span></strong>. L'imagerie de <strong><span class=\"kw-chiffre\">1ère intention</span></strong> est l'<span class=\"kw-imagerie\">écho-doppler artério-veineux</span>, toujours couplé à l'<span class=\"kw-bio\">IPS</span>.</p>\n      <table >\n        <thead><tr><th>Examen</th><th>Intérêt</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-imagerie\">IPS</span></strong></td><td><span class=\"kw-bio\">Systématique dans tous les cas</span> — oriente vers une participation artérielle</td></tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">Écho-doppler veineux</span></strong></td>\n            <td>\n              Membres inférieurs, en position <strong>debout</strong> :<br>\n              <strong>Reflux superficiel :</strong> précise le niveau de fuite et la topographie des perforantes<br>\n              <strong><span class=\"kw-radio\">Reflux profond</span> :</strong> quasi-synonyme de <span class=\"kw-etio\">syndrome post-thrombotique</span><br>\n              <strong><span class=\"kw-radio\">Obstruction profonde</span> :</strong> témoin d'un processus <span class=\"kw-etio\">thrombotique</span> ancien mal reperméabilisé ou récent\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">Écho-doppler artériel</span></strong></td>\n            <td>Confirme l'<span class=\"kw-etio\">artériopathie</span> ; précise le niveau, le type des lésions et le retentissement d'aval ; recherche un <strong>AAA</strong> (source d'emboles)</td>\n          </tr>\n          <tr><td><strong>Prélèvements spécifiques</strong></td><td>Si l'étiologie vasculaire n'est <strong>pas retenue</strong> : prélèvements bactériologiques, mycologiques, biopsiques</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 225 — Artériopathie oblitérante - anévrysme · 226 — Thrombose veineuse profonde - EP</em></p>","frequence":0},{"id":"228-12","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les modalités d’interprétation des pressions distales","contenu":"<p>L'<span class=\"kw-bio\">IPS</span> (<span class=\"kw-imagerie\">index de pression systolique</span>) et les pressions distales orientent le mécanisme de l'ulcère et le degré d'AOMI.</p>\n      <table >\n        <thead><tr><th>Valeur d'<span class=\"kw-imagerie\">IPS</span></th><th>Interprétation</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-chiffre\">0,9 – 1,3</span></td><td><span class=\"kw-imagerie\">IPS</span> de cheville <strong>normal</strong> = ulcère <span class=\"kw-etio\">veineux pur</span></td></tr>\n          <tr><td><span class=\"kw-chiffre\">0,7 – 0,9</span></td><td><span class=\"kw-imagerie\">IPS</span> diminué = ulcère <span class=\"kw-etio\">mixte à prédominance veineuse</span></td></tr>\n          <tr><td><span class=\"kw-chiffre\">&lt; 0,9</span></td><td><span class=\"kw-imagerie\">IPS</span> diminué = participation <span class=\"kw-etio\">artérielle</span></td></tr>\n          <tr><td><span class=\"kw-chiffre\">&gt; 1,3</span></td><td><span class=\"kw-alerte\">Artères calcifiées / incompressibles</span> — fréquent si <span class=\"kw-etio\">diabète</span>, <span class=\"kw-ci\">insuffisance rénale</span>, sujet âgé ; <span class=\"kw-imagerie\">IPS</span> ininterprétable</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Participation de l'AOMI à un symptôme de repos</strong> — la retenir si :\n        <br>• Pression de <strong>cheville</strong> <span class=\"kw-chiffre\">&lt; 50 mmHg</span>\n        <br>• Pression d'<strong>orteil</strong> <span class=\"kw-chiffre\">&lt; 30 mmHg</span>\n        <br>• <span class=\"kw-bio\">TcPO2</span> <span class=\"kw-chiffre\">&lt; 30 mmHg</span>\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 225 — Artériopathie oblitérante - anévrysme</em></p>","frequence":0},{"id":"228-13","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les trois phases de cicatrisation d’un ulcère","contenu":"<p>La cicatrisation d'un ulcère passe par <strong><span class=\"kw-def\">trois phases successives</span></strong> ; le traitement local doit être <strong>adapté à la phase en cours</strong>.</p>\n      <table >\n        <thead><tr><th>Phase</th><th>Objectif</th></tr></thead>\n        <tbody>\n          <tr><td><strong>1. Détersion</strong></td><td>Enlever la <span class=\"kw-clinique\">fibrine</span> et la <span class=\"kw-clinique\">nécrose</span> qui font obstacle au bourgeonnement</td></tr>\n          <tr><td><strong>2. <span class=\"kw-def\">Bourgeonnement</span></strong></td><td>Reconstitution du <span class=\"kw-def\">tissu de granulation</span> — ne doit pas être <strong>excessif</strong></td></tr>\n          <tr><td><strong>3. <span class=\"kw-def\">Ré-épithélialisation</span></strong></td><td>Recouvrement de la perte de substance par le <span class=\"kw-def\">néo-épiderme</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Le choix du pansement découle directement de la phase et de l'abondance des exsudats (voir objectif « soins locaux »).\n      </div>","frequence":0},{"id":"228-14","rang":"A","rubrique":"Prise en charge","titre":"Connaître les soins locaux, la gestion des exsudats, la détersion","contenu":"<p>Les soins locaux sont calqués sur les <strong>trois phases de cicatrisation</strong> ; le pansement est choisi selon la phase et l'abondance des exsudats.</p>\n      <table >\n        <thead><tr><th>Phase</th><th>Soins locaux</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Détersion</strong></td>\n            <td>\n              <strong>Lavage :</strong> doux à l'eau ou au savon, rinçage au sérum physiologique (eau stérile inutile)<br>\n              <strong>Antiseptiques :</strong> <span class=\"kw-ci\">pas d'antiseptique en l'absence d'infection déclarée</span> +++<br>\n              <strong>Détersion mécanique :</strong> avant tout ++ (curette, brosse, bistouri) ; sous anesthésie locale, MEOPA ou ALR<br>\n              <strong>Détersion chimique :</strong> alginates et hydrogels (laissés en place <span class=\"kw-chiffre\">48-72 h</span>)\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Bourgeonnement</span></strong></td>\n            <td>\n              <strong>Exsudats :</strong> privilégier les <span class=\"kw-ttt\">pansements absorbants</span> (éviter la macération péri-ulcéreuse)<br>\n              <strong>Produits :</strong> tulles vaselinés (sans <span class=\"kw-etio\">baume du Pérou</span>) ; hydrocolloïdes, hydrocellulaires, interfaces<br>\n              <strong>Plaie très exsudative :</strong> alginates de calcium (hémostatiques), hydrofibres\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Ré-épithélialisation</span></strong></td>\n            <td>\n              <strong>Produits :</strong> hydrocolloïdes et interfaces<br>\n              <strong>Greffes en pastilles / résille :</strong> effet <span class=\"kw-ttt\">antalgique</span> et raccourcissement de la cicatrisation ; indiquées si ulcère &gt;<span class=\"kw-chiffre\"> 10 cm</span> ou rebelle (&gt;<span class=\"kw-chiffre\"> 6 mois</span>)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>Type de plaie</th><th>Pansement recommandé</th></tr></thead>\n        <tbody>\n          <tr><td>Plaie <strong>sèche, nécrosée</strong></td><td><span class=\"kw-ttt\">Hydrogel</span></td></tr>\n          <tr><td>Plaie <strong>moyennement exsudative</strong></td><td><span class=\"kw-ttt\">Hydrocellulaire</span></td></tr>\n          <tr><td>Plaie <strong>très exsudative</strong></td><td><span class=\"kw-ttt\">Hydrofibre</span>, alginate, superabsorbant</td></tr>\n          <tr><td>Plaie <strong><span class=\"kw-etio\">hémorragique</span></strong></td><td><span class=\"kw-ttt\">Alginate</span></td></tr>\n          <tr><td>Plaie <strong>infectée</strong></td><td><span class=\"kw-ttt\">Pansement à l'argent</span></td></tr>\n          <tr><td><strong>Épidermisation</strong></td><td>Interface ou hydrocellulaire fin</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">\n        <strong>Proscrits.</strong> Les <span class=\"kw-ci\">antibiotiques locaux</span> et les <span class=\"kw-ci\">antiseptiques</span> sont <strong><span class=\"kw-ci\">contre-indiqués</span></strong> sur l'ulcère (en l'absence d'infection déclarée) — ils détruisent le milieu local favorable à la cicatrisation.\n      </div>","frequence":3},{"id":"228-15","rang":"A","rubrique":"Suivi et/ou pronostic","titre":"Connaître les complications des ulcères : allergies cutanées (eczéma de contact), infection et transformation maligne","contenu":"<p>Trois complications majeures sont attendues à l'EDN : l'<span class=\"kw-etio\">allergie cutanée</span>, l'<span class=\"kw-etio\">infection</span> et la <span class=\"kw-etio\">transformation maligne</span>.</p>\n      <table >\n        <thead><tr><th>Complication</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Dermatite de contact</span></strong><br>(<span class=\"kw-clinique\">eczéma</span> de contact)</td>\n            <td>\n              <strong>Mécanisme :</strong> fréquente du fait des nombreux topiques sur peau à barrière altérée<br>\n              <strong>Sémiologie :</strong> <span class=\"kw-clinique\">érythème microvésiculeux prurigineux</span> ; à évoquer devant un <span class=\"kw-alerte\">ulcère veineux qui devient douloureux</span><br>\n              <strong>Allergènes :</strong> <span class=\"kw-etio\">baume du Pérou</span>, antiseptiques, fragrances, lanoline, conservateurs, certains pansements<br>\n              <strong>PEC :</strong> éviction de l'allergène + <span class=\"kw-ttt\">dermocorticoïde</span> (<span class=\"kw-ci\">CI sur l'ulcération même</span>, possible en peau péri-ulcéreuse)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Surinfection microbienne</strong></td>\n            <td>\n              <strong><span class=\"kw-def\">Colonisation</span> :</strong> la présence de germes sur un ulcère n'est <strong>pas pathologique</strong> — pas de prélèvement ni d'<span class=\"kw-ttt\">antibiothérapie</span> systématiques<br>\n              <strong>Infection patente :</strong> évoquer si <span class=\"kw-clinique\">fièvre</span>, majoration de la douleur, inflammation des bords, <span class=\"kw-clinique\">lymphangite</span> → <span class=\"kw-etio\">dermohypodermite bactérienne</span>, rarement <span class=\"kw-etio\">fasciite nécrosante</span>, <span class=\"kw-alerte\">gangrène gazeuse</span> (<span class=\"kw-etio\">Clostridium perfringens</span>)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Transformation maligne</strong><br>(<span class=\"kw-etio\">carcinome épidermoïde</span>)</td>\n            <td>Complication rare et tardive — évoquer devant : chronicité, apparition de douleurs, hémorragie, <strong>bourgeonnement excessif</strong> de la plaie → <span class=\"kw-bio\">biopsie</span>, parfois à répéter</td>\n          </tr>\n          <tr>\n            <td><strong>Lésions ostéo-articulaires</strong></td>\n            <td>Périostite puis ostéopériostite → <span class=\"kw-alerte\">ankylose de la cheville</span> et attitudes vicieuses difficiles à corriger</td>\n          </tr>\n          <tr>\n            <td><strong>Hémorragie</strong></td>\n            <td>Surtout dans les ulcères veineux, par saignement d'une <strong>varice</strong></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">\n        <strong>Prévention non négociable.</strong> Mise à jour de la <span class=\"kw-alerte\">vaccination anti-tétanique</span> +++ — <strong>2/3 des infections à tétanos en Europe surviennent chez des patients porteurs d'un ulcère</strong> non vaccinés ou non à jour.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 350 — Grosse jambe rouge aiguë · 302 — <span class=\"kw-clinique\">Tumeur cutanée</span> - épithéliale - mélanique</em></p>","frequence":0}],"astuces":[],"strategie":{"redflags":"<ul><li><span class=\"kw-etio\">Ulcère artériel</span> / <span class=\"kw-alerte\">ischémie sévère</span> : ulcère <span class=\"kw-clinique\">creusant</span>, <span class=\"kw-alerte\">très douloureux</span>, <span class=\"kw-alerte\">pouls abolis</span> → <span class=\"kw-ttt\">revascularisation</span>, risque d'<span class=\"kw-alerte\">amputation</span></li><li><span class=\"kw-alerte\">Infection patente</span> : <span class=\"kw-clinique\">fièvre</span>, majoration de la douleur, <span class=\"kw-clinique\">inflammation des bords</span>, <span class=\"kw-clinique\">lymphangite</span> → <span class=\"kw-etio\">dermohypodermite bactérienne</span>, rarement <span class=\"kw-alerte\">fasciite nécrosante</span> ou <span class=\"kw-alerte\">gangrène gazeuse</span> (<span class=\"kw-etio\">Clostridium perfringens</span>)</li><li><span class=\"kw-etio\">Angiodermite nécrotique</span> : <span class=\"kw-alerte\">nécrose noirâtre</span> extensive, <span class=\"kw-alerte\">très douloureuse et insomniante</span> (pouls présents)</li><li>Absence de cicatrisation après <span class=\"kw-chiffre\">2–3 mois</span> de traitement bien conduit → reconsidérer l'étiologie + <span class=\"kw-bio\">biopsie</span></li><li><span class=\"kw-etio\">Transformation maligne</span> (<span class=\"kw-etio\">carcinome épidermoïde</span>) : <span class=\"kw-clinique\">bourgeonnement excessif</span>, apparition de douleurs ou d'<span class=\"kw-clinique\">hémorragie</span> sur ulcère chronique → <span class=\"kw-bio\">biopsie</span></li><li><span class=\"kw-alerte\">Statut antitétanique non à jour</span> → mise à jour de la <span class=\"kw-ttt\">vaccination anti-tétanique</span> (2/3 des tétanos en Europe surviennent sur ulcère)</li></ul>","principes":"<p>Traitement <strong>double</strong> : <span class=\"kw-def\">étiologique</span> (selon le mécanisme vasculaire) + <span class=\"kw-def\">local</span> (adapté aux 3 phases de cicatrisation). La <span class=\"kw-ttt\">compression</span> est le <strong>pilier de l'<span class=\"kw-clinique\">ulcère veineux</span></strong> ; <span class=\"kw-ci\">ne jamais</span> oublier la mise à jour <span class=\"kw-ttt\">antitétanique</span>.</p><p><strong>Compression <span class=\"q\">— pilier de l'<span class=\"kw-clinique\">ulcère veineux</span></span></strong></p><p><span class=\"kw-ci\">Contre-indiquée si IPS &lt; 0,6</span> ou ischémie sévère ; <span class=\"kw-ci\">inutile dans les ulcères non veineux</span></p><ul><li>Lutte contre l'<span class=\"kw-clinique\">œdème</span> et diminue le reflux ; <span class=\"kw-ttt\">haut niveau de pression</span> (<span class=\"kw-chiffre\">30–40 mmHg</span> à la cheville) si <span class=\"kw-chiffre\">IPS 0,8–1,3</span></li><li>Privilégier les <span class=\"kw-ttt\">compressions multicouches</span>, portées toute la journée</li></ul><p><strong><span class=\"kw-clinique\">Ulcère veineux</span></strong></p><ul><li><span class=\"kw-ttt\">Compression</span> systématique + soins locaux</li><li><span class=\"kw-ttt\">Chirurgie</span> : <span class=\"kw-ttt\">éveinage</span> ± <span class=\"kw-ttt\">sclérothérapie</span> si IVC superficielle sans obstruction/reflux profond axial</li><li>Cicatrisation attendue en <span class=\"kw-chiffre\">3–6 mois</span></li></ul><p><strong>Ulcère mixte <span class=\"q\">— à prédominance veineuse</span></strong></p><ul><li>Prendre en charge l'<span class=\"kw-etio\">AOMI</span> : <span class=\"kw-ttt\">revascularisation</span> souvent nécessaire</li><li>Compression seulement si <span class=\"kw-chiffre\">IPS &gt; 0,7</span> : pression abaissée <span class=\"kw-chiffre\">&lt; 30 mmHg</span>, <span class=\"kw-ttt\">bandes à étirement court</span> sous <span class=\"kw-def\">surveillance</span></li></ul><p><strong><span class=\"kw-clinique\">Ulcère artériel</span></strong></p><p><span class=\"kw-ci\">Compression contre-indiquée</span></p><ul><li><span class=\"kw-ttt\">Revascularisation</span> (<span class=\"kw-ttt\">pontage</span>, angioplastie) = priorité</li><li><span class=\"kw-ttt\">Vasodilatateurs</span>, <span class=\"kw-ttt\">analogues de la prostacycline</span> si ischémie grave</li><li><span class=\"kw-ttt\">Amputation</span> si <span class=\"kw-ttt\">revascularisation</span> impossible</li></ul><p><strong>Soins locaux <span class=\"q\">— 3 phases de cicatrisation</span></strong></p><p><span class=\"kw-ci\">Antibiotiques et antiseptiques locaux proscrits</span> (hors infection déclarée)</p><ul><li><strong>Détersion :</strong> <span class=\"kw-ttt\">détersion mécanique</span> avant tout (curette, sous anesthésie locale / MEOPA) ; <span class=\"kw-ci\">pas d'antiseptique en l'absence d'infection</span></li><li><strong>Bourgeonnement :</strong> <span class=\"kw-ttt\">pansements absorbants</span> (alginate, hydrofibre si très exsudatif) ; tulles vaselinés <span class=\"kw-ci\">sans baume du Pérou</span></li><li><strong>Ré-épithélialisation :</strong> <span class=\"kw-ttt\">hydrocolloïdes</span>, interfaces ; <span class=\"kw-ttt\">greffes en pastilles</span> si ulcère &gt;<span class=\"kw-chiffre\"> 10 cm</span> ou rebelle (&gt;<span class=\"kw-chiffre\"> 6 mois</span>)</li></ul><p><strong>Mesures générales & prévention</strong></p><ul><li>Mise à jour de la <span class=\"kw-ttt\">vaccination anti-tétanique</span> +++</li><li>Contrôle des <span class=\"kw-etio\">FDR cardiovasculaires</span> (tabac, <span class=\"kw-etio\">diabète</span>, HTA, poids) ; <span class=\"kw-ttt\">antiagrégant</span> si besoin</li><li>Évaluation nutritionnelle ; <span class=\"kw-ttt\">activité physique adaptée</span> / kinésithérapie (ankylose de cheville)</li></ul>","suivi":"<p><strong>Cicatrisation :</strong> <span class=\"kw-def\">réévaluation</span> à <span class=\"kw-chiffre\">2–3 mois</span> ; absence d'<span class=\"kw-clinique\">évolution</span> favorable sous traitement bien conduit → <span class=\"kw-bio\">biopsie</span> + reconsidérer l'étiologie.<br><strong><span class=\"kw-def\">Pronostic</span> :</strong> ulcère variqueux cicatrise en <span class=\"kw-chiffre\">3–6 mois</span> ; ulcère <span class=\"kw-etio\">post-thrombotique</span> = le plus chronique et rebelle ; <span class=\"kw-clinique\">ulcère artériel</span> → <span class=\"kw-alerte\">amputation</span> si <span class=\"kw-ttt\">revascularisation</span> impossible.<br><strong>Complications à dépister :</strong> <span class=\"kw-etio\">dermatite de contact</span> (<span class=\"kw-clinique\">ulcère veineux</span> qui (re)devient douloureux), <span class=\"kw-etio\">surinfection</span>, <span class=\"kw-etio\">carcinome épidermoïde</span>, <span class=\"kw-alerte\">ankylose de cheville</span>, <span class=\"kw-clinique\">hémorragie</span> d'une varice.<br><strong>Récidive :</strong> fréquente, passage à la chronicité non rare → poursuivre la <span class=\"kw-ttt\">compression</span> au long cours.</p>"},"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Ulcère de jambe chronique (> 1 mois) — Bilan vasculaire systématique : IPS + écho-doppler artério-veineux + palpation des pouls","detail":"<h4>CAT — orientation étiologique devant un ulcère de jambe — Tri sur le bilan vasculaire : <span class=\"kw-imagerie\">IPS</span> + <span class=\"kw-imagerie\">écho-doppler</span> artério-veineux + pouls</h4>","branches":[{"to":"q-ips","label":"Anomalie vasculaire (veineuse et/ou artérielle)","color":"amber"},{"to":"q-nonvasc","label":"Examens artériels ET veineux normaux","color":"blue"}]},{"id":"q-ips","kind":"decision","label":"IPS de cheville + pouls périphériques ? — À coupler à l'écho-doppler et à l'aspect de l'ulcère","branches":[{"to":"t-veineux","label":"IPS 0,9–1,3 · pouls présents · signes d'IVC","color":"amber"},{"to":"t-mixte","label":"IPS 0,7–0,9 · pouls abolis sur ulcère d'allure veineuse","color":"amber"},{"to":"t-arteriel","label":"IPS < 0,9 marqué ou pouls abolis · ulcère artériel distal","color":"red"}]},{"id":"t-veineux","kind":"terminal","label":"Ulcère veineux","color":"amber","detail":"<h4>Confirmation</h4><ul><li><span class=\"kw-def\">Terrain</span> : <span class=\"kw-clinique\">femme &gt; 50 ans</span>, ATCD de <span class=\"kw-etio\">TVP</span> / varices / surpoids</li><li>Ulcère <span class=\"kw-clinique\">péri-malléolaire</span> étendu, bords réguliers, <span class=\"kw-clinique\">peu douloureux</span>, fond <span class=\"kw-clinique\">exsudatif fibrineux</span></li><li>Signes d'<span class=\"kw-def\">IVC</span> : <span class=\"kw-clinique\">dermite ocre</span>, <span class=\"kw-clinique\">atrophie blanche</span>, <span class=\"kw-clinique\">couronne phlébectasique</span></li><li><span class=\"kw-chiffre\">IPS 0,9–1,3</span> ; <span class=\"kw-imagerie\">écho-doppler veineux</span> (reflux superficiel/profond, obstruction)</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Compression</span> à haut niveau (<span class=\"kw-chiffre\">30–40 mmHg</span>), multicouches</li><li><span class=\"kw-ttt\">Soins locaux</span> adaptés à la phase de cicatrisation</li><li><span class=\"kw-ttt\">Chirurgie</span> : <span class=\"kw-ttt\">éveinage</span> ± <span class=\"kw-ttt\">sclérothérapie</span></li></ul><h4>Renvoi</h4><ul><li>Item 226 (thrombose veineuse profonde - EP)</li></ul>"},{"id":"t-mixte","kind":"terminal","label":"Ulcère mixte (prédominance veineuse)","color":"amber","detail":"<h4>Reconnaître</h4><ul><li>Ulcère d'<span class=\"kw-clinique\">allure veineuse à cicatrisation traînante</span> + <span class=\"kw-alerte\">pouls abolis</span></li><li><span class=\"kw-chiffre\">IPS 0,7–0,9</span> (ou <span class=\"kw-chiffre\">&gt; 1,3</span> incompressible si <span class=\"kw-etio\">diabète</span> / <span class=\"kw-ci\">insuffisance rénale</span>)</li></ul><h4>Conduite</h4><ul><li>Prendre en charge l'<span class=\"kw-etio\">AOMI</span> : <span class=\"kw-ttt\">revascularisation</span> souvent nécessaire</li><li><span class=\"kw-ttt\">Compression adaptée</span> seulement si <span class=\"kw-chiffre\">IPS &gt; 0,7</span> : pression <span class=\"kw-chiffre\">&lt; 30 mmHg</span>, <span class=\"kw-ttt\">bandes à étirement court</span> sous <span class=\"kw-def\">surveillance</span></li></ul><h4>Renvoi</h4><ul><li>Item 225 (artériopathie oblitérante - anévrysme)</li></ul>"},{"id":"t-arteriel","kind":"terminal","label":"Ulcère artériel","color":"red","detail":"<h4>Confirmation</h4><ul><li><span class=\"kw-def\">Terrain</span> : <span class=\"kw-clinique\">homme &gt; 50 ans</span>, <span class=\"kw-etio\">FDR cardiovasculaires</span>, <span class=\"kw-clinique\">claudication</span> d'effort</li><li>Ulcère <span class=\"kw-clinique\">creusant</span> de petite taille, <span class=\"kw-alerte\">douloureux</span>, distal (zones d'appui), fond <span class=\"kw-clinique\">atone</span></li><li>Peau <span class=\"kw-clinique\">luisante, dépilée, froide</span> ; <span class=\"kw-alerte\">pouls abolis</span></li><li><span class=\"kw-chiffre\">IPS &lt; 0,9</span> ; <span class=\"kw-imagerie\">écho-doppler artériel</span> (recherche aussi un AAA)</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Revascularisation</span> (<span class=\"kw-ttt\">pontage</span>, angioplastie) = priorité</li><li><span class=\"kw-ttt\">Vasodilatateurs</span>, <span class=\"kw-ttt\">analogues de la prostacycline</span> si ischémie grave</li><li><span class=\"kw-ttt\">Amputation</span> si <span class=\"kw-ttt\">revascularisation</span> impossible</li></ul><h4>Gravité</h4><ul><li><span class=\"kw-alerte\">Ischémie critique</span> : risque d'<span class=\"kw-alerte\">amputation</span> et de <span class=\"kw-alerte\">gangrène gazeuse</span> ; <span class=\"kw-ci\">compression contre-indiquée</span></li></ul><h4>Renvoi</h4><ul><li>Item 225 (artériopathie oblitérante - anévrysme)</li></ul>"},{"id":"q-nonvasc","kind":"decision","label":"Nécrose très douloureuse sur terrain HTA / diabète ? — Pouls présents, grands axes vasculaires normaux","branches":[{"to":"t-angiodermite","label":"Oui · nécrose noirâtre à bords irréguliers","color":"red"},{"to":"t-nonvasc","label":"Non · drapeaux rouges (évolution atypique, pas de cicatrisation à 2–3 mois)","color":"blue"}]},{"id":"t-angiodermite","kind":"terminal","label":"Angiodermite nécrotique (ulcère de Martorell)","color":"red","detail":"<h4><span class=\"kw-def\">Terrain</span></h4><ul><li><span class=\"kw-clinique\">Femme &gt; 50 ans</span>, <span class=\"kw-etio\">HTA</span> ++, <span class=\"kw-etio\">diabète</span> ++</li></ul><h4>Reconnaître</h4><ul><li>Début par une <span class=\"kw-clinique\">plaque purpurique ou livedoïde</span> → <span class=\"kw-alerte\">nécrose noirâtre</span> à <span class=\"kw-clinique\">bords irréguliers</span> « en carte de géographie »</li><li>Face antéro-externe de jambe ; <span class=\"kw-alerte\">très douloureuse, insomniante</span></li><li>Pouls présents, grands axes artériels et veineux normaux</li></ul><h4>Mécanisme</h4><ul><li><span class=\"kw-def\">Infarctus cutané</span> par <span class=\"kw-def\">occlusion artériolaire</span> (artériolosclérose dermique)</li></ul><h4>Conduite</h4><ul><li>Traitement de la <span class=\"kw-alerte\">douleur</span> + des FDR (<span class=\"kw-etio\">HTA</span>, <span class=\"kw-etio\">diabète</span>)</li><li><span class=\"kw-ttt\">Exérèse de la nécrose</span></li><li><span class=\"kw-ttt\">Greffes cutanées précoces</span> (effet cicatrisant et <span class=\"kw-ttt\">antalgique</span>)</li></ul><h4>Renvoi</h4><ul><li>Item 224 (<span class=\"kw-etio\">HTA</span>) · Item 247 (diabète)</li></ul>"},{"id":"t-nonvasc","kind":"terminal","label":"Ulcère non vasculaire","color":"blue","detail":"<h4>Quand y penser</h4><ul><li>Examens artériels et veineux <strong>normaux</strong></li><li><span class=\"kw-clinique\">Évolution</span> rapide, ou traînante et inhabituelle ; absence de cicatrisation après <span class=\"kw-chiffre\">2–3 mois</span></li><li>Anomalie du fond, du bord, de la périphérie, ou siège atypique</li></ul><h4>Étiologies</h4><ul><li><span class=\"kw-etio\">Mal perforant plantaire</span> (<span class=\"kw-etio\">diabète</span>, neuropathies)</li><li><span class=\"kw-etio\">Ecthyma</span> (<span class=\"kw-bio\">Streptocoque A</span>) ; mycobactérioses, mycoses, parasitoses</li><li><span class=\"kw-etio\">Pyoderma gangrenosum</span> (<span class=\"kw-etio\">MICI</span>, hémopathie, cancer)</li><li>Hémopathies : <span class=\"kw-etio\">drépanocytose</span>, syndromes myéloprolifératifs</li><li><span class=\"kw-etio\">Carcinome épidermoïde</span> et autres cancers cutanés</li><li>Vascularites : <span class=\"kw-etio\">SAPL</span>, PAN, lupus, cryoglobulinémies</li><li>Médicaments : <span class=\"kw-ttt\">hydroxy-urée</span>, <span class=\"kw-ttt\">interféron</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-bio\">Biopsie</span> + prélèvements bactériologiques / mycologiques ; traiter la <span class=\"kw-etio\">cause</span></li></ul><h4>Renvoi</h4><ul><li>Item 247 (<span class=\"kw-etio\">diabète</span>) · Item 282 (MICI) · Item 302 (<span class=\"kw-clinique\">tumeur cutanée</span> - épithéliale - mélanique)</li></ul>"}]},"cards":[{"i":"35de3966cbc1","n":228,"o":"228-1","u":"Définition","t":"Connaître la définition d’un ulcère de jambe","q":"Quelle est l'origine la plus fréquente des ulcères de jambe au niveau des membres inférieurs ?","a":"<p>L'ulcère de jambe est le plus souvent d'origine <strong>vasculaire</strong> (veineuse et/ou artérielle), secondaire à une <strong>ischémie tissulaire</strong>.</p>"},{"i":"39282ef5c53f","n":228,"o":"228-1","u":"Définition","t":"Connaître la définition d’un ulcère de jambe","q":"Quel est l'impact épidémiologique de l'ulcère de jambe en France ?","a":"<p>L'ulcère de jambe est une pathologie <strong>fréquente et invalidante</strong>, responsable de nombreuses hospitalisations. Sa prévalence augmente avec l'âge, atteignant <strong>2 à 5 % après 80 ans</strong>. Il existe une prédominance féminine pour l'ulcère veineux (<strong>1,5 femme pour 1 homme</strong>).</p>"},{"i":"f184d3a119b6","n":228,"o":"228-1","u":"Définition","t":"Connaître la définition d’un ulcère de jambe","q":"Quelle est la définition d'un ulcère de jambe ?","a":"<p>Un ulcère de jambe est une <strong>perte de substance dermique chronique</strong> (évoluant depuis <strong>plus d'un mois</strong>) qui ne cicatrise pas.</p>"},{"i":"52bdb39b58eb","n":228,"o":"228-10","u":"Prise en charge","t":"Connaître la compression et ses modalités","q":"Quelles sont les modalités de compression spécifiques pour un ulcère mixte à prédominance veineuse ?","a":"<p>Pour un ulcère mixte à prédominance veineuse :</p><ul><li>La compression est autorisée seulement si l'<strong>IPS > 0,7</strong>.</li><li>La <strong>pression doit être abaissée</strong>, généralement <strong>inférieure à 30 mmHg</strong>.</li><li>Le matériel privilégié est constitué de <strong>bandes à étirement court</strong>, sous surveillance médicale stricte.</li></ul>"},{"i":"79e3fbc7a061","n":228,"o":"228-10","u":"Prise en charge","t":"Connaître la compression et ses modalités","q":"Quelles sont les modalités de compression recommandées pour un ulcère veineux pur (IPS 0,8 – 1,3) ?","a":"<p>Pour un ulcère veineux pur (IPS 0,8 – 1,3), les modalités sont :</p><ul><li><strong>Pression :</strong> haut niveau, typiquement <strong>30-40 mmHg à la cheville</strong>.</li><li><strong>Classe :</strong> <strong>Classe 3</strong> (25-36 mmHg) pour les ulcères cicatrisés ; <strong>Classe 4</strong> (> 36 mmHg) pour les ulcères ouverts.</li><li><strong>Modalités :</strong> privilégier les <strong>compressions multicouches</strong>, port toute la journée.</li></ul>"},{"i":"a03174f422ca","n":228,"o":"228-10","u":"Prise en charge","t":"Connaître la compression et ses modalités","q":"Dans quels cas la compression est-elle inutile, voire contre-indiquée, dans la prise en charge des ulcères de jambe ?","a":"<p>La compression est <strong>inutile dans les ulcères non veineux</strong>. Elle est <strong>contre-indiquée</strong> de manière formelle en cas d'<strong>ischémie sévère</strong> ou d'<strong>ulcère artériel</strong>, notamment si l'<strong>IPS est inférieur à 0,6</strong>.</p>"},{"i":"c5804b3e17eb","n":228,"o":"228-10","u":"Prise en charge","t":"Connaître la compression et ses modalités","q":"Quel est le principe essentiel et les bénéfices de la compression dans la prise en charge de l'ulcère de jambe, notamment veineux ?","a":"<p>La compression est le <strong>pilier du traitement de l'ulcère veineux</strong>. Son principe est de lutter contre l'<strong>œdème</strong> et de diminuer le <strong>reflux veineux</strong>, favorisant ainsi la cicatrisation de ces ulcères.</p>"},{"i":"27b956395ce8","n":228,"o":"228-11","u":"Examens complémentaires","t":"Connaître l’intérêt de l’imagerie : échodoppler artério-veineux en 1ère intention","q":"Quel est l'intérêt de l'écho-doppler artériel des membres inférieurs dans le bilan d'un ulcère de jambe ?","a":"<ul><li>Il confirme une éventuelle <strong>artériopathie</strong>.</li><li>Il précise le <strong>niveau et le type des lésions</strong>.</li><li>Il évalue le <strong>retentissement d'aval</strong>.</li><li>Il recherche un <strong>Anévrysme de l'Aorte Abdominale (AAA)</strong> qui pourrait être une source d'emboles.</li></ul>"},{"i":"73122db5e634","n":228,"o":"228-11","u":"Examens complémentaires","t":"Connaître l’intérêt de l’imagerie : échodoppler artério-veineux en 1ère intention","q":"Quel est l'intérêt de l'écho-doppler veineux des membres inférieurs dans le bilan d'un ulcère de jambe ?","a":"<ul><li>Il est réalisé en <strong>position debout</strong>.</li><li>Il recherche un <strong>reflux superficiel</strong> (précise le niveau de fuite et la topographie des perforantes).</li><li>Il recherche un <strong>reflux profond</strong> (quasi-synonyme de syndrome post-thrombotique).</li><li>Il recherche une <strong>obstruction profonde</strong> (témoin d'un processus thrombotique ancien mal reperméabilisé ou récent).</li></ul>"},{"i":"f7f994fed86b","n":228,"o":"228-11","u":"Examens complémentaires","t":"Connaître l’intérêt de l’imagerie : échodoppler artério-veineux en 1ère intention","q":"Quel est l'examen d'imagerie de première intention à réaliser devant un ulcère de jambe ?","a":"<p>L'examen d'imagerie de première intention est l'<strong>écho-doppler artério-veineux</strong> des membres inférieurs, toujours couplé à la mesure de l'<strong>Index de Pression Systolique (IPS)</strong>.</p>"},{"i":"23192a1d779c","n":228,"o":"228-13","u":"Diagnostic positif","t":"Connaître les trois phases de cicatrisation d’un ulcère","q":"Quelle est la première phase de cicatrisation d'un ulcère et quel est son objectif principal ?","a":"<p>La première phase de cicatrisation d'un ulcère est la phase de <strong>détersion</strong>. Son objectif principal est d'<strong>enlever la fibrine et la nécrose</strong> qui font obstacle au bourgeonnement.</p>"},{"i":"494d41a6b63b","n":228,"o":"228-13","u":"Diagnostic positif","t":"Connaître les trois phases de cicatrisation d’un ulcère","q":"Quelle est la troisième et dernière phase de cicatrisation d'un ulcère et quel est son but ?","a":"<p>La troisième phase de cicatrisation d'un ulcère est la <strong>ré-épithélialisation</strong>. Son but est le <strong>recouvrement de la perte de substance par le néo-épiderme</strong>.</p>"},{"i":"531adcd755a5","n":228,"o":"228-13","u":"Diagnostic positif","t":"Connaître les trois phases de cicatrisation d’un ulcère","q":"Quelle est la deuxième phase de cicatrisation d'un ulcère et que signifie-t-elle ?","a":"<p>La deuxième phase de cicatrisation d'un ulcère est la phase de <strong>bourgeonnement</strong>. Elle correspond à la <strong>reconstitution du tissu de granulation</strong>, qui ne doit pas être excessif.</p>"},{"i":"04503d6cb9a6","n":228,"o":"228-14","u":"Prise en charge","t":"Connaître les soins locaux, la gestion des exsudats, la détersion","q":"Quels sont les principes généraux du lavage et de l'utilisation des antiseptiques dans les soins locaux de l'ulcère de jambe ?","a":"<p>Le lavage doit être <strong>doux</strong>, avec de l'eau ou du savon, suivi d'un rinçage au <strong>sérum physiologique</strong>. L'eau stérile est inutile. Les antiseptiques sont <strong>proscrits en l'absence d'infection déclarée</strong> car ils détruisent le milieu local favorable à la cicatrisation.</p>"},{"i":"113df4f90a79","n":228,"o":"228-14","u":"Prise en charge","t":"Connaître les soins locaux, la gestion des exsudats, la détersion","q":"Comment doit-on gérer les exsudats d'un ulcère de jambe en phase de bourgeonnement et quels types de pansements sont recommandés ?","a":"<p>Il faut privilégier les <strong>pansements absorbants</strong> pour éviter la macération péri-ulcéreuse.</p><ul><li>Pour les plaies très exsudatives : <strong>alginates de calcium</strong> (hémostatiques) ou <strong>hydrofibres</strong>.</li><li>Autres options : tulles vaselinés (sans baume du Pérou), hydrocolloïdes, hydrocellulaires, interfaces.</li></ul>"},{"i":"609902845c77","n":228,"o":"228-14","u":"Prise en charge","t":"Connaître les soins locaux, la gestion des exsudats, la détersion","q":"Quels types de pansements sont spécifiquement contre-indiqués pour l'ulcère de jambe en l'absence d'infection déclarée ?","a":"<p>Les <strong>antibiotiques locaux</strong> et les <strong>antiseptiques</strong> sont formellement contre-indiqués sur l'ulcère en l'absence d'infection déclarée, car ils détruisent le milieu local favorable à la cicatrisation.</p>"},{"i":"66d26434524d","n":228,"o":"228-14","u":"Prise en charge","t":"Connaître les soins locaux, la gestion des exsudats, la détersion","q":"Quels sont les pansements appropriés en phase de ré-épithélialisation pour un ulcère de jambe ?","a":"<p>Les pansements recommandés sont les <strong>hydrocolloïdes</strong> et les <strong>interfaces</strong>. Des greffes en pastilles ou en résille peuvent être indiquées si l'ulcère mesure <strong>plus de 10 cm</strong> ou est <strong>rebelle</strong> (&gt; 6 mois), car elles ont un effet antalgique et raccourcissent la durée de cicatrisation.</p>"},{"i":"979783021622","n":228,"o":"228-14","u":"Prise en charge","t":"Connaître les soins locaux, la gestion des exsudats, la détersion","q":"Quelles sont les méthodes de détersion d'un ulcère de jambe et quand sont-elles indiquées ?","a":"<ul><li>La <strong>détersion mécanique</strong> est le premier choix (curette, brosse, bistouri), souvent réalisée sous anesthésie locale, MEOPA ou ALR.</li><li>La <strong>détersion chimique</strong> utilise des produits comme les alginates et les hydrogels, laissés en place <strong>48 à 72 heures</strong>.</li></ul>"},{"i":"16966c4083f7","n":228,"o":"228-15","u":"Suivi et/ou pronostic","t":"Connaître les complications des ulcères : allergies cutanées (eczéma de contact), infection et transformation maligne","q":"Quand doit-on évoquer une infection patente d'un ulcère de jambe et quelles en sont les formes graves ?","a":"<p>Une infection patente est à évoquer si le patient présente une <strong>fièvre</strong>, une <strong>majoration de la douleur</strong>, une inflammation des bords de l'ulcère ou une <strong>lymphangite</strong>. Cela peut conduire à une <strong>dermohypodermite bactérienne</strong>. Des formes rares mais graves incluent la <strong>fasciite nécrosante</strong> et la <strong>gangrène gazeuse</strong> due à <em>Clostridium perfringens</em>.</p>"},{"i":"2def4e2fdf81","n":228,"o":"228-15","u":"Suivi et/ou pronostic","t":"Connaître les complications des ulcères : allergies cutanées (eczéma de contact), infection et transformation maligne","q":"Quels sont les allergènes courants impliqués dans la dermatite de contact d'un ulcère de jambe et comment la prendre en charge ?","a":"<p>Les allergènes incluent le <strong>baume du Pérou</strong>, les antiseptiques, les fragrances, la lanoline, les conservateurs et certains pansements. La prise en charge consiste en l'<strong>éviction de l'allergène</strong> et l'application de <strong>dermocorticoïdes</strong>, possibles sur la peau péri-ulcéreuse mais contre-indiqués sur l'ulcération même.</p>"},{"i":"55ba1fb8b279","n":228,"o":"228-15","u":"Suivi et/ou pronostic","t":"Connaître les complications des ulcères : allergies cutanées (eczéma de contact), infection et transformation maligne","q":"Quand doit-on suspecter une transformation maligne d'un ulcère de jambe et quel est l'examen clé pour la confirmer ?","a":"<p>La transformation maligne en <strong>carcinome épidermoïde</strong> est rare et tardive. Elle doit être suspectée devant une <strong>chronicité</strong> de l'ulcère, l'apparition de <strong>douleurs</strong>, une <strong>hémorragie</strong> ou un <strong>bourgeonnement excessif</strong> de la plaie. L'examen clé est la <strong>biopsie</strong>, parfois à répéter.</p>"},{"i":"8cac61bf8d39","n":228,"o":"228-15","u":"Suivi et/ou pronostic","t":"Connaître les complications des ulcères : allergies cutanées (eczéma de contact), infection et transformation maligne","q":"Quels sont les mécanismes et la sémiologie d'une dermatite de contact liée à un ulcère de jambe ?","a":"<p>La dermatite de contact est fréquente en raison de l'utilisation de nombreux topiques sur une peau dont la barrière est altérée. La sémiologie se caractérise par un <strong>érythème microvésiculeux prurigineux</strong>. Elle doit être évoquée devant un ulcère veineux qui devient <strong>douloureux</strong>.</p>"},{"i":"337e969f08f2","n":228,"o":"228-2","u":"Diagnostic positif","t":"Savoir diagnostiquer un ulcère veineux, artériel, mixte","q":"Qu'est-ce qui doit faire évoquer un ulcère mixte et comment le confirme-t-on ?","a":"<p>Un ulcère mixte doit être évoqué devant :</p><ul><li>Un ulcère d'<strong>allure veineuse</strong> (localisation, aspect) mais avec une <strong>cicatrisation traînante</strong>.</li><li>La présence de <strong>pouls abolis</strong>.</li><li>Une <strong>pression d'orteil abaissée</strong>.</li></ul><p>Le diagnostic est confirmé par la réalisation systématique d'un <strong>écho-doppler veineux</strong> des membres inférieurs et la mesure de l'<strong>IPS</strong>. Un <strong>écho-doppler artériel</strong> est réalisé si les pouls sont abolis, si des signes d'AOMI sont présents, ou si l'IPS est inférieur à 0,9 ou supérieur à 1,3.</p>"},{"i":"48419bbfd973","n":228,"o":"228-2","u":"Diagnostic positif","t":"Savoir diagnostiquer un ulcère veineux, artériel, mixte","q":"Comment différencier un ulcère veineux, un ulcère artériel et un ulcère mixte à l'aide de l'IPS et de l'écho-doppler ?","a":"<p>La différenciation repose sur :</p><ul><li><strong>Indice de Pression Systolique (IPS) :</strong><ul><li><strong>Ulcère veineux pur :</strong> IPS entre <strong>0,9 et 1,3</strong> (normal).</li><li><strong>Ulcère artériel :</strong> IPS <strong>inférieur à 0,9</strong>.</li><li><strong>Ulcère mixte :</strong> IPS entre <strong>0,7 et 0,9</strong> (prédominance veineuse avec AOMI modérée) ; un IPS <strong>supérieur à 1,3</strong> suggère des artères calcifiées masquant une artériopathie.</li></ul></li><li><strong>Écho-doppler :</strong><ul><li><strong>Ulcère veineux :</strong> <strong>Écho-doppler veineux des membres inférieurs</strong> (réalisé debout) met en évidence un reflux superficiel/profond ou une obstruction profonde.</li><li><strong>Ulcère artériel :</strong> <strong>Écho-doppler artériel</strong> confirme l'artériopathie, son niveau et son type de lésions, et peut rechercher un Anévrisme de l'Aorte Abdominale (AAA).</li><li><strong>Ulcère mixte :</strong> Si les pouls sont abolis, s'il existe des signes d'AOMI ou si l'IPS est anormal (&lt; 0,9 ou &gt; 1,3), un <strong>écho-doppler artériel</strong> est également indiqué en complément de l'écho-doppler veineux.</li></ul></li></ul>"},{"i":"523fa1d2eda4","n":228,"o":"228-2","u":"Diagnostic positif","t":"Savoir diagnostiquer un ulcère veineux, artériel, mixte","q":"Quels sont les éléments clés du diagnostic clinique d'un ulcère artériel de jambe ?","a":"<p>Le diagnostic clinique de l'ulcère artériel de jambe repose sur :</p><ul><li>Un <strong>terrain évocateur</strong> : homme de plus de 50 ans, facteurs de risque cardiovasculaires (FDRCV), antécédents d'ischémie d'effort (claudication intermittente).</li><li>Une <strong>localisation typique</strong> : zones de frottement/appui (orteils, dos et bord externe du pied, talon), parfois face antérieure de jambe (ulcère « suspendu »).</li><li>Une <strong>douleur intense</strong>.</li><li>Un fond <strong>creusant, atone (pâle, propre)</strong>, avec un risque d'exposition des articulations/tendons/os.</li><li>Des signes cutanés périphériques d'<strong>ischémie</strong> : peau luisante, dépilée, baisse de la température cutanée, pâleur à la surélévation, érythro-cyanose de déclivité, allongement du temps de recoloration pulpaire.</li><li>Une <strong>abolition des pouls périphériques</strong>.</li></ul>"},{"i":"b266cf0b53dd","n":228,"o":"228-2","u":"Diagnostic positif","t":"Savoir diagnostiquer un ulcère veineux, artériel, mixte","q":"Quels sont les éléments clés du diagnostic clinique d'un ulcère veineux de jambe ?","a":"<p>Le diagnostic clinique de l'ulcère veineux de jambe repose sur :</p><ul><li>Un <strong>terrain évocateur</strong> : femme de plus de 50 ans, antécédents de TVP, varices, surpoids.</li><li>Une <strong>localisation typique</strong> : péri-malléolaire jusqu'au 1/3 inférieur du mollet, avec des bords réguliers.</li><li>Une <strong>douleur peu ou pas intense</strong>.</li><li>Un fond <strong>superficiel, non creusant, exsudatif et fibrineux</strong>.</li><li>Des signes cutanés péri-ulcéreux d'<strong>insuffisance veineuse chronique</strong> : varices, télangiectasies, couronne phlébectasique, dermite ocre, atrophie blanche, eczéma variqueux, lipodermatosclérose.</li><li>Des pouls périphériques <strong>normaux</strong>.</li></ul>"},{"i":"169365535469","n":228,"o":"228-4","u":"Contenu multimédia","t":"Photographie d’un ulcère veineux typique","q":"Quelle est l'apparence des bords et du fond d'un ulcère veineux typique ?","a":"<p>Les bords sont <strong>réguliers</strong>, souples et au même niveau que l'ulcère. Le fond est souvent <strong>étendu</strong>, <strong>fibrineux et exsudatif</strong>, et superficiel, <strong>non creusant</strong>.</p>"},{"i":"87fb541fc284","n":228,"o":"228-4","u":"Contenu multimédia","t":"Photographie d’un ulcère veineux typique","q":"Quels sont les signes cutanés péri-ulcéreux associés à un ulcère veineux typique ?","a":"<ul><li><strong>Dermite ocre</strong></li><li><strong>Atrophie blanche</strong></li><li><strong>Eczéma variqueux</strong></li><li>Présence de <strong>varices</strong> et d'une <strong>couronne phlébectasique</strong></li></ul>"},{"i":"cd50a5fa0780","n":228,"o":"228-4","u":"Contenu multimédia","t":"Photographie d’un ulcère veineux typique","q":"Quelles sont les caractéristiques du siège d'un ulcère veineux typique ?","a":"<p>L'ulcère veineux typique se localise préférentiellement en région <strong>péri-malléolaire</strong>, le plus souvent au niveau de la <strong>malléole interne</strong>, et peut s'étendre jusqu'au <strong>tiers inférieur du mollet</strong>.</p>"},{"i":"f1331ec3b0fc","n":228,"o":"228-4","u":"Contenu multimédia","t":"Photographie d’un ulcère veineux typique","q":"Comment identifier un ulcère veineux typique sur une photographie ?","a":"<p>Un ulcère veineux typique est une ulcération située de façon <strong>péri-malléolaire</strong>, étendue, avec des <strong>bords réguliers</strong>. Son fond est <strong>fibrineux et exsudatif</strong>, et il est entouré de signes d'insuffisance veineuse périphérique.</p>"},{"i":"260a1c5a7207","n":228,"o":"228-5","u":"Contenu multimédia","t":"Photographie d’un ulcère artériel typique","q":"Quelles sont les caractéristiques sémiologiques des douleurs associées à un ulcère artériel typique ?","a":"<p>Les douleurs associées à un ulcère artériel typique sont habituellement <strong>intenses</strong> et <strong>douloureuses</strong>.</p>"},{"i":"3b326a52b577","n":228,"o":"228-5","u":"Contenu multimédia","t":"Photographie d’un ulcère artériel typique","q":"Quelle est la description générale d'un ulcère artériel typique ?","a":"<p>L'ulcère artériel typique est une <strong>ulcération de petite taille</strong>, <strong>creusante</strong>, dont le <strong>fond atone est pâle</strong>. Il siège volontiers sur une <strong>zone d'appui ou de frottement du pied</strong>, sur une peau <strong>luisante, dépilée et froide</strong>.</p>"},{"i":"709e4126c3a9","n":228,"o":"228-5","u":"Contenu multimédia","t":"Photographie d’un ulcère artériel typique","q":"Quelles sont les caractéristiques de la peau péri-ulcéreuse et des pouls en cas d'ulcère artériel typique ?","a":"<ul><li>La peau péri-ulcéreuse est <strong>luisante</strong>, <strong>dépilée</strong> et <strong>froide</strong>.</li><li>On observe également une <strong>pâleur à la surélévation</strong> et une <strong>érythro-cyanose de déclivité</strong>.</li><li>Les <strong>pouls sont abolis</strong>.</li></ul>"},{"i":"7866c7e593ab","n":228,"o":"228-5","u":"Contenu multimédia","t":"Photographie d’un ulcère artériel typique","q":"Quels sont les sièges préférentiels d'un ulcère artériel typique ?","a":"<p>L'ulcère artériel typique siège principalement sur les <strong>zones de frottement ou d'appui</strong> telles que les <strong>orteils</strong>, le <strong>dos et le bord externe du pied</strong>, ou le <strong>talon</strong>. Il peut parfois se retrouver sur la <strong>face antérieure de la jambe</strong> (ulcère « suspendu »).</p>"},{"i":"7fb8328329fb","n":228,"o":"228-5","u":"Contenu multimédia","t":"Photographie d’un ulcère artériel typique","q":"Quelles sont les caractéristiques de la taille et du fond d'un ulcère artériel typique ?","a":"<p>L'ulcère artériel typique est de <strong>petite taille</strong>, <strong>creusant</strong> (avec un risque d'exposition tendineuse/osseuse), et son <strong>fond est atone</strong> (pâle et propre).</p>"}]};